    sourceQuestionNumber: 63,
    topic: "Comprehension",
    subtopic: "Gadyalu",
    question: "పద్యాన్ని గుండెలు చీల్చుకొని పోయేలాగా రచించిన భావకవి శ్రీనాయని సుబ్బారావు. సౌభద్రుని ప్రణయ యాత్ర, ఫలశ్రుతి, మాతృగీతాలు భావకవితాశాఖకు చెందినవి. స్వాతంత్ర్యానంతరం ఆయన రచించిన కావ్యాల్లో 'వేదనా వాసుదేవము', జన్మభూమి సంప్రదాయ పద్ధతిలోనివి. జీవితానుభవాలు గానం చేశాక శ్రీ నాయని అంతర్ముఖులై రచించిన కావ్యం వేదనా వాసుదేవము. జన్మభూమోహపటిమ చేత తాను జన్మించిన పొదిలె సీమ మహిమలను, అందచందాలను, ఆ సీమతో తనకున్న వీడరాని బంధాన్ని “జన్మభూమి”లో వర్ణించారు.\nనాయని సుబ్బారావు స్వాతంత్ర్యానంతర రచన",
